static ssize_t write_maxblksize ( struct file * file , char * buf , size_t size ) { char * mesg = buf ; struct nfsd_net * nn = net_generic ( netns ( file ) , nfsd_net_id ) ; if ( size > 0 ) { int bsize ; int rv = get_int ( & mesg , & bsize ) ; bsize = max_t ( int , bsize , 1024 ) ; bsize = min_t ( int , bsize , NFSSVC_MAXBLKSIZE ) ; bsize &= ~ ( 1024 - 1 ) ; mutex_lock ( & nfsd_mutex ) ; if ( nn -> nfsd_serv ) { mutex_unlock ( & nfsd_mutex ) ; return - EBUSY ; } nfsd_max_blksize = bsize ; mutex_unlock ( & nfsd_mutex ) ; } return scnprintf ( buf , SIMPLE_TRANSACTION_LIMIT , "%d\n" , nfsd_max_blksize ) ; } 